export class Owner {
  readonly path: string;
  constructor(
    readonly dir: string,
    readonly boot: Bootstrap,
    readonly api: PaseoApi,
  ) {
    this.path = join(dir, "state.json");
  }
  async read() {
    return (await readJson<State>(this.path)) ?? empty();
  }

